# New Mexico, San Miguel County: a first scatter of old buildings, from the Pecos valley to the Conchas plains.
# Facts come from the National Register records and forms (tools/form.py), Wikipedia articles read as raw text,
# and the pages linked on each place.
from data_b import N
from data_ma import W
def NR(n,t): return ['National Register record: '+t,'https://npgallery.nps.gov/AssetDetail/NRIS/'+n]
BATCH={'key':'nm_wrcv','label':'New Mexico, San Miguel County','added':'2026-11-28 04:36'}
PLACES=[
N('san-antonio-de-padua-church-pecos','San Antonio de Padua Church','Pecos','nm','worship','standing',35.58304,-105.67583,'exact','view','drive','','1903–1906',
  'The village church of Pecos, built by its parishioners in 1903–06 under their French priests, Father Maxime Mayeux and then Father Edward Paulhan, to whom the design is credited. It is a cross-shaped building of locally quarried granite and sandstone, built to serve the Catholic parish of an Hispanic village that church records first mention about 1825. The National Register form says it was listed in 1978 as a state-level site.',
  'A square entrance tower with a shingled belfry and a cross on top, red sandstone around the doorway and in the corner stones of the tower, an arched stained-glass transom over heavy wooden doors, and a low broken-course stone wall round the churchyard and the old graveyard (campo santo). In the tower porch, heavy beams are carved with a pattern of diagonal lines and small crosses. Standing-seam metal roof. The form (1978) described the inside only as far as the porch and choir loft; the rest of the interior was not checked here.',
  'A French-built stone church beside a village that grew up north of the ruined mission at Pecos.',
  'Beside State Road 63 in Pecos, on parish ground; the churchyard walls and graves are part of it. Look from the road and the churchyard edge. Service times were not read from the parish\'s own page, so check with the parish before going in.',
  [NR('78001826','San Antonio de Padua Church'),W('San Antonio de Padua Church')],brick='no',bcol='none',hours='?',th=[35.58284,-105.67565],thn='Parish lot, St. Anthony\'s Loop'),
N('pendaries-grist-mill-rociada','Pendaries Grist Mill','Rociada','nm','industry','standing',35.84306,-105.39632,'site','view','drive','','1875–1876',
  'Jean Pendaries, a Frenchman who built the Plaza Hotel in Las Vegas, built this flour mill in 1875–76 in the Rociada valley. The National Register form says the millstones came overland by ox team from Westport Landing (Kansas City) and that the mill could turn out about 8,000 pounds of flour in 24 hours. It was a three-story building with adobe-brick walls, stuccoed in the 1950s. By the time of the 1979 listing it held a general store and a lounge.',
  'A three-story gabled building with stuccoed adobe walls. The 1979 form says the mill race and wooden water wheel had been replaced but that the milling machinery inside was still as installed a century before, with a rock floor at ground level and wooden floors above, and two big millstones set by the store door. Wikipedia calls it perhaps the best preserved gristmill in New Mexico. Whether it is open now, and how the 2022 Calf Canyon fire affected the valley round it, were not checked.',
  'A Frenchman\'s flour mill, with its machinery still inside.',
  'Private property about 1.6 km east of Rociada off NM 105 (the form lists private owners in 1979; the present owner was not checked). Treat it as view-only from the public road and ask before going closer.',
  [NR('79001552','Pendaries Grist Mill'),['National Register form (1979)','https://npgallery.nps.gov/GetAsset/5122b026-b512-473c-bf65-55c53891711f/'],W('Rociada, New Mexico')],brick='no',bcol='none'),
N('variadero-bridge','Variadero Bridge','Variadero','nm','landmark','standing',35.38933,-104.4598,'exact','view','drive','','c. 1915',
  'A 200-foot concrete bridge over the Rio Conchas, built in the late 1910s when San Miguel County put up four concrete pony-truss bridges. George E. Morrison, a civil engineer in Las Vegas, designed it for the Missouri Valley Bridge and Iron Company, which built it under contract to the county. It now carries only local traffic in the village, on an old line of NM 104.',
  'Four 50-foot reinforced-concrete spans on three piers, with trusses five feet high, 29 inches of that below the road deck. A metal plaque naming the county commissioners and the engineer is fixed to it, and the rotted remains of an old wooden river-gauging station cling to the middle pier.',
  'A county\'s concrete bridge, a century on and still carrying cars.',
  'In the village of Variadero, on a former line of NM 104 now used as a local road. Who owns the road was not checked, so look from the roadside; no parking was checked.',
  [NR('97000736','Variadero Bridge'),['National Register form (1997)','https://npgallery.nps.gov/GetAsset/36859c38-194c-4f31-884b-5809a4728d8d']],brick='no',bcol='none'),
N('pecos-river-bridge-terrero','Pecos River Bridge at Terrero','Terrero','nm','landmark','standing',35.74045,-105.67826,'exact','public','walk','','1921',
  'A one-span timber truss bridge built by the U.S. Forest Service in 1921 to cross the Pecos River beside the old mining camp of Terrero. A newer bridge on NM 63 replaced it, and the old one is kept as a footbridge and horse bridge. In 1944 rotted parts were replaced with salvaged steel rails and hangers from old bridges.',
  'A 75-foot Howe through truss with five panels, 10-by-10 inch timber diagonals and steel rods for the uprights, resting on two concrete abutments (a timber pier was added later). It stands in a high mountain canyon just west of the newer road bridge.',
  'A Forest Service timber bridge saved beside the road that replaced it.',
  'On the Santa Fe National Forest side of NM 63 at the river crossing at Terrero; the form says the State Highway Department looks after it. Park beside the road and walk the few steps; parking was not checked further.',
  [NR('97000739','Pecos River Bridge at Terrero'),['National Register form (1997)','https://npgallery.nps.gov/GetAsset/e52c94ce-9fe0-4c2c-97e6-980645035b8a']],brick='no',bcol='none'),
N('san-miguel-del-vado','San Miguel del Vado','San Miguel','nm','town','standing',35.3631,-105.45072,'area','view','drive','','1794–',
  'The first village founded in this part of the Pecos valley, settled in 1794 by Genízaros, Pecos Indians, converted Comanches, Spanish soldiers and families from Peña Blanca. Its name is the ford where wagons crossed the Pecos River. By 1804 it petitioned the Bishop of Durango for a church, begun the next year, and the trader William Becknell was welcomed here in 1821 on his first Santa Fe Trail journey. An 1827 census showed about 2,893 inhabitants in the Spanish period.',
  'The old plaza layout, in two big half-plazas on either side of State Road 3, with the Pecos River ford still visible at the southeast corner of the village, and adobe houses. This is a living village of private homes, so the pin is the middle of the district, not one building.',
  'The Santa Fe Trail\'s first village west of the plains, still on its plaza.',
  'A village of private homes about 3 miles south of US 84 on NM 3. Stay on the public road and the plazas, and ask before going onto private land. The church was not checked for visiting hours.',
  [NR('72000809','San Miguel del Vado Historic District'),['National Register form (1972)','https://npgallery.nps.gov/GetAsset/d0d645fd-4b3f-47e3-a4eb-c1f61c8783ac'],W('San Miguel del Vado, New Mexico')],brick='no',bcol='none'),
N('glorieta-baldy-lookout-tower','Glorieta Baldy Lookout Tower','La Cueva','nm','landmark','standing',35.65,-105.79978,'site','view','hike','','1940',
  'A steel fire lookout tower on the summit of Glorieta Baldy in the Santa Fe National Forest, built in 1940 and listed on the National Register in 1988. A news report says the Civilian Conservation Corps built it. The Register calls it San Miguel County and Wikipedia says Santa Fe County. In 2017 it was reported to be in disrepair, with a plan by the Friends of the Santa Fe National Forest to restore it for the Forest Service cabin rental program.',
  'A tower with a cab on top, at the head of Glorieta Baldy Road (Forest Road 375). The Forest Service page says the lookout is closed until further notice, so view it from outside and do not climb it.',
  'A CCC-era fire tower on a mountaintop above the Pecos valley.',
  'Santa Fe National Forest land. The Forest Service\'s own page says the lookout is closed until further notice; the road is Forest Road 375. How far a car can go, and the state of the road, were not checked.',
  [NR('87002492','Glorieta Baldy Lookout Tower'),['Forest Service: Glorieta Baldy Lookout','https://www.fs.usda.gov/r03/santafe/recreation/glorieta-baldy-lookout'],W('Glorieta Baldy Lookout Tower')],brick='no',bcol='none',conf='mixed'),
N('atsf-roundhouse-las-vegas-nm','Santa Fe Railway roundhouse, Las Vegas','Las Vegas','nm','rail','standing',35.58674,-105.21536,'site','view','drive','','1917',
  'A railroad division headquarters brought mechanics and trainmen to Las Vegas, and a nine-stall roundhouse was built in 1880, enlarged to sixteen stalls in 1899 and replaced in 1917 by a 34-stall roundhouse of reinforced concrete that cost about $200,000 (Wikipedia says the earlier building burned on August 6, 1917). At its peak 380 men worked here in three shifts. Falling rail traffic, the Depression and diesel engines that ran straight through from La Junta, Colorado, to Albuquerque closed it.',
  'A three-quarter circle 675 feet around its inside curve, with 19-inch concrete walls on the outside, 13-inch brick walls on the inside, big industrial metal windows, sliding wooden doors and brick floors. It stands at the south end of Railroad Avenue beside the tracks and the Gallinas River. In 1985 it served as a farm-supply warehouse with its windows closed up; the NRHS roundhouse list gives city and county storage, undated. Present use not checked.',
  'A 34-stall concrete roundhouse where Santa Fe steam engines were inspected.',
  'Private or city storage use was recorded, not a public site: look from Railroad Avenue and the road by the river, and do not go onto the rail yard.',
  [NR('85002621','AT & SF Roundhouse'),W('AT & SF Roundhouse')],brick='?',bcol='',conf='mixed'),
N('ilfeld-memorial-chapel-las-vegas','Charles Ilfeld Memorial Chapel','Las Vegas','nm','worship','standing',35.5967,-105.23824,'site','view','drive','','1912',
  'Paid for in 1912 by Charles Ilfeld, the territory\'s leading nineteenth-century merchant, this chapel in the Masonic Cemetery also served as the cemetery caretaker\'s house. The National Register form calls it one of the most richly finished Tudor Revival buildings in New Mexico. Seven years later Ilfeld paid for the Adele Ilfeld Auditorium at Highlands University in memory of his wife.',
  'An L-shaped building of rock-faced brown sandstone with reddish mortar, buttresses at the ends and middle, a wood-shingle roof with exposed rafters and bracketed beams, half-timbering in the gable, and red brick quoins at the chapel door and brick around the windows. In 1985 the windows and doors were boarded up. Present condition and any opening were not checked.',
  'A Tudor Revival chapel with red brick trim, in a hilltop cemetery.',
  'In the Masonic Cemetery, owned by the Masonic Temple in 1985, about 100 feet southwest of Colonias and Romero Streets. Look from the cemetery road and ask the cemetery\'s keepers about going in.',
  [NR('85002657','Ilfeld, Charles, Memorial Chapel'),W('Charles Ilfeld Memorial Chapel')],brick='some',bcol='red'),
N('taichert-building-las-vegas','Taichert Building','Las Vegas','nm','civic','standing',35.59375,-105.22277,'exact','view','drive','','1900',
  'A business block built in 1900 with a store in front, storage behind and rooms to live in above. A saloon and rooms came first, then a grocery and a laundry. The brothers Joseph and Milton Taichert bought it in 1916 and used it to clean, sort and auction wool, hides and furs for buyers who travelled through New Mexico, Arizona and Colorado, until the business closed in 1971.',
  'Twelve-inch common-bond brick walls (the 1985 form says stuccoed; a recent photograph shows red brick), a flat roof with a pressed-metal cornice and brick dentils, bay windows (oriels) with moulded cornices, and, on the side wall, a painted sign still reading "Raw Furs / S.A. Taichert & Co. / Compradores de Pieles Crudas y Lana". It stood vacant in 1985; present use not checked.',
  'A wool-and-furs warehouse whose painted sign outlasted the business.',
  'On National Street, half a block east of the river, in Las Vegas\'s New Town. Look from the sidewalk; the interior was not checked.',
  [NR('85002616','Taichert Building')],brick='yes',bcol='red'),
N('eldorado-hotel-las-vegas-nm','Eldorado Hotel','Las Vegas','nm','hotel','standing',35.59431,-105.21394,'exact','view','drive','','1898–1902',
  'Built between 1898 and 1902 as the Eldorado Hotel, it was briefly the Monticello Hotel and later became the Vincente Salazar Senior Citizen\'s Center. The National Register form calls it perhaps the leading remaining example of the local brickwork style that grew up after a brickyard opened in 1898.',
  'Brick walls with a stepped parapet over a corbelled brick cornice, recessed panels, a continuous projecting brick sill and paired brick arches on the second floor, and new ground-floor windows under corbelled arches on piers. In 1985 the city owned it. Present use not checked.',
  'A Richardsonian-arched hotel in the local brick style.',
  'Owned by the city of Las Vegas when listed (1985); on Grand Avenue facing US 85, in the Railroad Avenue historic area. Look from the street; whether the building is open now was not checked.',
  [NR('85002626','Eldorado Hotel'),W('Eldorado Hotel')],brick='?',bcol=''),
N('presbyterian-mission-church-las-vegas-nm','Presbyterian Mission Church','Las Vegas','nm','worship','standing',35.58942,-105.22674,'exact','view','drive','','1871–1873',
  'The first Protestant church built in Las Vegas, put up in 1871–73 with 30-inch adobe walls, and described in the 1978 National Register form as the oldest Protestant church building left in New Mexico. A later preservation page calls it the second oldest; the two do not agree. The carpenter David H. Powell was paid $650 for the woodwork in October 1871.',
  'A 100-by-25-foot adobe church with a gabled portico on four square columns made of boards nailed around timbers, a rose window in the pediment and a tall belfry. The form calls the temple front unique in Territorial-period New Mexico. Three stone buttresses support the north wall. It stands at Chavez and Socorro Streets, three blocks south of the old plaza. Services and opening times were not checked.',
  'A temple-front adobe church that brought Eastern fashion to the old plaza town.',
  'At 1413 Chavez Street on a residential block; look from the street and ask the congregation about visiting. A low brown-sandstone wall surrounds the lot.',
  [NR('78001825','Presbyterian Mission Church'),['Cornerstones: Las Vegas Presbyterian Mission','https://www.cstones.org/past-projects-3/2018/3/8/las-vegas-presbyterian-mission-las-vegas-new-mexico'],W('Presbyterian Mission Church')],brick='no',bcol='none',conf='mixed'),
N('adele-ilfeld-auditorium-las-vegas','Adele Ilfeld Auditorium','Las Vegas','nm','civic','standing',35.59475,-105.2198,'exact','view','drive','','1914–1931',
  'The New Mexico legislature voted $75,000 in 1914 for an auditorium at what is now New Mexico Highlands University; the Las Vegas architect E. W. Hart designed it in brownstone Romanesque Revival, like Springer Hall. War delays left the money short, and on October 19, 1919 Charles Ilfeld gave $25,000 in memory of his wife Adele. It was dedicated in 1928 and not fully furnished until February 7, 1931, seventeen years after the vote.',
  'Brown brick with a rock-faced brownstone front, three round-arched doorways on modified Doric columns, tower-like parapets with a triple arch, corbels along the gable and stained-glass side windows. The 1979 form found the inside austere and run down; present condition and public access were not checked.',
  'A campus auditorium that took seventeen years to finish.',
  'On the New Mexico Highlands University campus in Las Vegas; the university owns it. Look from the campus paths; opening for events was not checked.',
  [NR('80002568','Ilfeld, Adele, Auditorium'),['National Register form (1980)','https://npgallery.nps.gov/GetAsset/01280a77-0c51-4bd6-aa3a-5aeee99ce4d9'],W('Adele Ilfeld Auditorium')],brick='no',bcol='dark'),
N('old-post-office-las-vegas-nm','Old Las Vegas Post Office','Las Vegas','nm','civic','standing',35.59331,-105.21869,'exact','view','drive','','1927',
  'Built in 1927 under the supervising architect James A. Wetmore in Washington, who chose Georgian Revival, a popular eastern style, instead of a local one: the Register form calls it the best of only a handful of Georgian Revival buildings in New Mexico. It replaced a wood-frame synagogue that was moved three blocks. By 1985 it held the offices of the East Las Vegas city schools.',
  'A flat-roofed building with a brick parapet and stone balustrade, a stone cornice with dentils, paired recessed upper windows, tall first-floor windows with scroll keystones and arch accents, and doorways with fanlights and wrought-iron grilles; the front entrance has rusticated quoins. It stands at Douglas and Ninth Streets, at the foot of University Hill.',
  'A New England post office dropped into New Mexico.',
  'City school offices in 1985; present use and whether the public may enter were not checked. Look from the sidewalk at 901 Douglas.',
  [NR('85002598','Old Las Vegas Post Office')],brick='yes',bcol='red'),
N('rogers-administration-building-las-vegas','Rogers Administration Building','Las Vegas','nm','civic','standing',35.59534,-105.22004,'area','view','drive','','1933',
  'Designed by John Gaw Meem and built in 1933 as a library on the New Mexico Highlands University campus, a Works Progress Administration project. The 1988 Register form calls it a fine example of a modified Spanish Colonial style and the only campus building in that nomination.',
  'A T-shaped, two-story masonry and stucco building with a French tile roof, scroll-shaped stone brackets under the eaves, stone corner quoins, arched second-story windows separated by Corinthian-like pilasters, and a deep arched doorway with a cartouche panel. It is now the university\'s administration building.',
  'A Meem-designed library turned university offices.',
  'Owned by the university\'s regents; the public may look from the campus on National Avenue. Whether visitors may go in was not checked.',
  [NR('88001559','Rogers Administration Building'),['National Register form (1988)','https://npgallery.nps.gov/GetAsset/da4eb000-274e-455e-ad04-325b50d0ba8e']],brick='no',bcol='none'),
]
